<script setup lang="ts">import { nextTick, ref, watch } from 'vue'; import type { ChronicleEvent } from '../types'; const props = defineProps<{ entries: ChronicleEvent[] }>(); const scroll = ref<HTMLElement>(); watch(() => props.entries, () => nextTick(() => { if (scroll.value) scroll.value.scrollTop = 0 }), { deep: true })</script>
<template><footer class="chronicles-bar"><span class="chronicles-title">◆ 门中纪事</span><div ref="scroll" class="chronicles-scroll"><span v-if="!entries.length" class="chr-empty">山门初立，尚无纪事。</span><template v-else><span v-for="(event, i) in entries.slice(-15).reverse()" :key="i" class="chr-entry"><span v-if="event.year" class="chr-date">第{{ event.year }}年{{ event.month }}月 </span><span :class="`chr-${event.mood}`">{{ event.text }}</span></span><span v-if="entries.length > 15" class="text-[.65rem] text-ink-fade">…… 更早的纪事 ……</span></template></div></footer></template>

